{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01MqG2RcUXErRP8ggnKzaseo","type":"tool_result","content":"1\t'''This module contains all high-level helpers function that allow to work with\n2\tCyclomatic Complexity\n3\t'''\n4\t\n5\timport math\n6\t\n7\tfrom radon.visitors import GET_COMPLEXITY, ComplexityVisitor, code2ast\n8\t\n9\t# sorted_block ordering functions\n10\tSCORE = lambda block: -GET_COMPLEXITY(block)\n11\tLINES = lambda block: block.lineno\n12\tALPHA = lambda block: block.name\n13\t\n14\t\n15\tdef cc_rank(cc):\n16\t    r'''Rank the complexity score from A to F, where A stands for the simplest\n17\t    and best score and F the most complex and worst one:\n18\t\n19\t    ============= =====================================================\n20\t        1 - 5        A (low risk - simple block)\n21\t        6 - 10       B (low risk - well structured and stable block)\n22\t        11 - 20      C (moderate risk - slightly complex block)\n23\t        21 - 30      D (more than moderate risk - more complex block)\n24\t        31 - 40      E (high risk - complex block, alarming)\n25\t        41+          F (very high risk - error-prone, unstable block)\n26\t    ============= =====================================================\n27\t\n28\t    Here *block* is used in place of function, method or class.\n29\t\n30\t    The formula used to convert the score into an index is the following:\n31\t\n32\t    .. math::\n33\t\n34\t        \\text{rank} = \\left \\lceil \\dfrac{\\text{score}}{10} \\right \\rceil\n35\t        - H(5 - \\text{score})\n36\t\n37\t    where ``H(s)`` stands for the Heaviside Step Function.\n38\t    The rank is then associated to a letter (0 = A, 5 = F).\n39\t    '''\n40\t    if cc < 0:\n41\t        raise ValueError('Complexity must be a non-negative value')\n42\t    return chr(\n43\t        min(int(math.ceil(cc / 10.0) or 1) - (1, 0)[5 - cc < 0], 5) + 65\n44\t    )\n45\t"}]},"parent_tool_use_id":null,"session_id":"a53b5df8-af34-471d-a95e-3827129cc483","uuid":"4802c566-99a1-4f1b-bf19-63c70ef512a9","timestamp":"2026-11-07T14:13:18.747Z","tool_use_result":{"type":"text","file":{"filePath":"/home/user/earshot_d2/ws/workspace/radon/complexity.py","content":"'''This module contains all high-level helpers function that allow to work with\nCyclomatic Complexity\n'''\n\nimport math\n\nfrom radon.visitors import GET_COMPLEXITY, ComplexityVisitor, code2ast\n\n# sorted_block ordering functions\nSCORE = lambda block: -GET_COMPLEXITY(block)\nLINES = lambda block: block.lineno\nALPHA = lambda block: block.name\n\n\ndef cc_rank(cc):\n    r'''Rank the complexity score from A to F, where A stands for the simplest\n    and best score and F the most complex and worst one:\n\n    ============= =====================================================\n        1 - 5        A (low risk - simple block)\n        6 - 10       B (low risk - well structured and stable block)\n        11 - 20      C (moderate risk - slightly complex block)\n        21 - 30      D (more than moderate risk - more complex block)\n        31 - 40      E (high risk - complex block, alarming)\n        41+          F (very high risk - error-prone, unstable block)\n    ============= =====================================================\n\n    Here *block* is used in place of function, method or class.\n\n    The formula used to convert the score into an index is the following:\n\n    .. math::\n\n        \\text{rank} = \\left \\lceil \\dfrac{\\text{score}}{10} \\right \\rceil\n        - H(5 - \\text{score})\n\n    where ``H(s)`` stands for the Heaviside Step Function.\n    The rank is then associated to a letter (0 = A, 5 = F).\n    '''\n    if cc < 0:\n        raise ValueError('Complexity must be a non-negative value')\n    return chr(\n        min(int(math.ceil(cc / 10.0) or 1) - (1, 0)[5 - cc < 0], 5) + 65\n    )\n","numLines":45,"startLine":1,"totalLines":109}},"tool_result_meta":[{"id":"toolu_01MqG2RcUXErRP8ggnKzaseo","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}]}
